code:
// Grafana alert rule -- pseudocode representation of the UI configuration

alert_rule: "No records processed in 25 hours"
data_source: CloudWatch
query: |
  Namespace: Pipeline/Orders
  MetricName: RecordsProcessed
  Dimensions: { Source: "*" }        // wildcard -- one series per source
  Statistic: Sum
  Period: 1h
condition: |
  last(query) == 0 over last 25h
evaluation_interval: 15m
for: 0m
labels:
  team: data-platform
  severity: critical

alert_rule: "Error rate above 5 percent"
query: "Metric Math: 100 * (ValidationErrors.Sum / RecordsProcessed.Sum)"
condition: "query > 5"
evaluation_interval: 5m
for: 10m
labels: { team: data-platform, severity: warning }

// Notification policy tree (Terraform provider example)
resource "grafana_notification_policy" "root" {
  contact_point = "slack-data-platform"
  group_by      = ["alertname"]

  policy {
    matcher { label = "severity"; match = "="; value = "critical" }
    contact_point = "pagerduty-oncall"
    continue      = false
  }
  policy {
    matcher { label = "source"; match = "="; value = "Bloomberg" }
    contact_point = "slack-bloomberg-team"
  }
}

resource "grafana_contact_point" "slack" {
  name = "slack-data-platform"
  slack {
    url = var.slack_webhook_url
    title = "{{ .CommonLabels.alertname }}"
  }
}
